INSERT INTO products
(id, name, name_en, description, description_en, price, original_price, category, type, images, stock, rating, reviews, tags, unit, unit_type, story, culture, how_to_use, status, votes_count, preorder_end, on_sale_at)
VALUES
  ('panda-egg', '熊猫蛋仔', 'Panda Egg', '手作釉烧陶瓷蛋,剥开是一只熊猫。首批限量编号。', 'A hand-glazed ceramic egg that "hatches" into a panda. First batch, individually numbered.', 29.99, NULL, 'decor', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=cute%20minimalist%20ceramic%20panda%20egg%20figurine%2C%20white%20glazed%20porcelain%20with%20black%20panda%20face%2C%20product%20photo%20on%20light%20gray%20background%2C%20soft%20shadow&image_size=square_hd']::text[], 0, 0, 0, ARRAY['handmade','limited','panda']::text[], NULL, NULL, '第一款作品。我们想做一个"剥开有惊喜"的东西——蛋是最日常的食物,熊猫是成都最松弛的居民。', '', '', 'preorder', 0, '2026-09-12T22:23:56.509Z', '2026-09-19T22:23:56.509Z'),
  ('panda-lantern', '熊猫月灯', 'Panda Moon Lantern', '抱月熊猫小夜灯,暖光硅胶灯罩,投票达标开模。', 'A panda hugging the moon — a warm-glow bedside night light. Molds open when votes reach the goal.', 39.99, NULL, 'home', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=minimalist%20panda%20shaped%20bedside%20lantern%20lamp%2C%20warm%20glow%2C%20white%20and%20black%20design%2C%20product%20photo%20on%20beige%20background&image_size=square_hd']::text[], 0, 0, 0, ARRAY['lamp','panda','cozy']::text[], NULL, NULL, '打样到第4版,我们把耳朵从"立耳"改成了"垂耳"——成都的熊猫,松弛感最重要。材质暂定柔光硅胶+实木底座。', '', '', 'design', 247, NULL, NULL),
  ('bamboo-ruler', '竹节尺', 'Bamboo Joint Ruler', '竹节造型黄铜书签尺,刻一只趴着的熊猫。', 'A brass bookmark-ruler shaped like a bamboo joint, engraved with a lounging panda.', 18.99, NULL, 'stationery', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=minimalist%20bamboo%20ruler%20with%20engraved%20panda%20pattern%2C%20stationery%20product%20photo%20on%20white%20background&image_size=square_hd']::text[], 0, 0, 0, ARRAY['brass','stationery']::text[], NULL, NULL, '成都是一座被竹子养着的城市。我们把竹节做成尺子,让"成都节奏"躺在你的书里。', '', '', 'design', 183, NULL, NULL),
  ('lazy-panda-plush', '躺平熊猫玩偶', 'Lazy Panda Plush', '一个彻底躺平的熊猫,可以当抱枕也可以当情绪搭子。', 'A panda that has fully given in to lying flat. A pillow, a mood, a companion.', 34.99, NULL, 'toy', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=minimalist%20lying%20flat%20lazy%20panda%20plush%20toy%2C%20black%20and%20white%20soft%20fabric%2C%20product%20photo%20on%20light%20gray%20background&image_size=square_hd']::text[], 0, 0, 0, ARRAY['plush','cute','gift']::text[], NULL, NULL, '成都熊猫基地里最受欢迎的不是最活泼的,而是躺得最平的那只。它教会我们:不努力,也很可爱。', '', '', 'design', 312, NULL, NULL),
  ('panda-bookmark', '熊猫书签套装', 'Panda Bookmark Set', '四枚金属镂空熊猫书签,读书也要有成都节奏。', 'Four hollow-cut metal panda bookmarks. Reading at Chengdu pace.', 12.99, NULL, 'stationery', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=set%20of%20minimalist%20metal%20panda%20bookmarks%2C%20black%20and%20silver%2C%20stationery%20flat%20lay%20on%20white%20background&image_size=square_hd']::text[], 200, 4.9, 86, ARRAY['stationery','gift']::text[], NULL, NULL, '', '', '', 'on-sale', 0, NULL, NULL),
  ('rong-tote', '蓉云帆布袋', 'Rong Cloud Tote', '厚磅帆布,水墨熊猫线条,装电脑也装菜。', 'Heavy-weight canvas tote with ink-wash panda lines. Fits a laptop, fits groceries.', 24.99, NULL, 'home', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=natural%20canvas%20tote%20bag%20with%20minimalist%20black%20panda%20line%20art%20print%2C%20product%20photo%20on%20white%20background&image_size=square_hd']::text[], 150, 4.8, 64, ARRAY['canvas','daily']::text[], NULL, NULL, '', '', '', 'on-sale', 0, NULL, NULL),
  ('chengdu-postcard', '成都明信片', 'Chengdu Postcard Set', '八张黑白水墨熊猫×成都地标,寄给想念的人。', 'Eight black-and-white ink postcards: pandas x Chengdu landmarks, for someone you miss.', 15.99, NULL, 'stationery', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=set%20of%20minimalist%20Chengdu%20panda%20illustration%20postcards%2C%20black%20and%20white%20ink%20style%2C%20flat%20lay%20on%20white%20table&image_size=square_hd']::text[], 300, 4.9, 112, ARRAY['postcard','ink']::text[], NULL, NULL, '', '', '', 'on-sale', 0, NULL, NULL),
  ('panda-teapet', '熊猫茶宠', 'Panda Tea Pet', '茶席上的小熊猫,浇热水会开心得变色(待定款)。', 'A tiny panda for your tea tray, that changes color when bathed in hot tea.', 19.99, NULL, 'decor', 'physical', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=small%20cute%20ceramic%20panda%20tea%20pet%20figurine%2C%20glossy%20black%20and%20white%20glaze%2C%20product%20photo%20on%20light%20gray%20background&image_size=square_hd']::text[], 120, 4.7, 43, ARRAY['tea','ceramic']::text[], NULL, NULL, '', '', '', 'on-sale', 0, NULL, NULL)
INSERT INTO blogs
(id, slug, title, title_en, content, content_en, category, images, audio, video, author, publish_date, views)
VALUES
  ('1', 'panda-egg-making-of', '熊猫蛋仔诞生记:一颗蛋里怎么住进一只熊猫', 'Making of Panda Egg: How a Panda Moved Into an Egg', '第一款作品,我们想做一个"剥开有惊喜"的东西。蛋是最日常的食物,熊猫是成都最松弛的居民——把它俩放在一起,就有了熊猫蛋仔。这篇文章记录了从草图、3D 打样到釉烧的全过程,以及我们为什么坚持首批限量编号。', 'For our first piece, we wanted something with a surprise inside. The egg is the most everyday food, and the panda is Chengdu''s most relaxed resident. This post documents the journey from sketch to 3D prototype to glazed ceramic, and why the first batch is individually numbered.', 'art', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=designer%20desk%20with%20ceramic%20panda%20egg%20sketches%20and%20clay%20prototypes%2C%20black%20and%20white%20minimal%20workshop&image_size=landscape_16_9']::text[], NULL, NULL, 'Chengdu Craft Studio', '2026-08-28', 2341),
  ('2', 'why-we-let-you-vote', '为什么下一款做什么,由你投票决定', 'Why You Get to Vote on What We Make Next', '小工作室最怕自嗨:我们觉得可爱的,未必是你想放在桌上的。所以我们把设计稿提前展出,票数达标才开模生产。这篇文章讲讲"投票-预售-生产"的节奏,以及你的一票如何决定一款产品的命运。', 'A small studio''s biggest fear is making things nobody wants. So we show concepts early, and only open molds when votes hit the goal. This post explains our vote, pre-order and production rhythm, and how one vote decides a product''s fate.', 'culture', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=minimal%20design%20studio%20wall%20with%20panda%20product%20concept%20sketches%20pinned%2C%20black%20white%20style&image_size=landscape_16_9']::text[], NULL, NULL, 'Chengdu Craft Studio', '2026-08-20', 1892),
  ('3', 'chengdu-relaxation-design', '松弛感设计:成都教给我们的产品哲学', 'Designing with Relaxation: What Chengdu Taught Us', '成都熊猫基地里最受欢迎的不是最活泼的熊猫,而是躺得最平的那只。这座城市的节奏慢慢渗进了我们的设计:不追求复杂功能,只做你每天愿意看到、愿意握住的小物件。', 'At the panda base, the most beloved panda is not the most active one, it is the one lying flattest. Chengdu''s pace has seeped into our design: no complicated features, just small objects you are happy to see and hold every day.', 'culture', ARRAY['https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=lazy%20giant%20panda%20lying%20on%20wooden%20platform%2C%20black%20and%20white%20minimal%20photography&image_size=landscape_16_9']::text[], NULL, NULL, 'Chengdu Craft Studio', '2026-08-12', 1567)
